// Code node - Atribuição de Placement do anúncio Meta
const insights = $input.first().json.data || [];

// Função pra limpar placements duplicados (ex: instagram_instagram_stories → instagram_stories)
function formatarPlacement(plataforma, posicao) {
  const posicaoLimpa = posicao.replace(`${plataforma}_`, '');
  return `${plataforma}_${posicaoLimpa}`;
}

// Filtra apenas placements com cliques > 0
const comCliques = insights
  .filter(p => parseInt(p.clicks) > 0)
  .sort((a, b) => parseInt(b.clicks) - parseInt(a.clicks));

let placementAtribuido;
let confianca;

if (comCliques.length === 0) {
  const maiorImpressao = insights
    .sort((a, b) => parseInt(b.impressions) - parseInt(a.impressions))[0];
  placementAtribuido = maiorImpressao
    ? formatarPlacement(maiorImpressao.publisher_platform, maiorImpressao.platform_position)
    : 'desconhecido';
  confianca = 'baixa';
} else if (comCliques.length === 1) {
  placementAtribuido = formatarPlacement(comCliques[0].publisher_platform, comCliques[0].platform_position);
  confianca = 'alta';
} else {
  const comCTR = comCliques.map(p => ({
    ...p,
    ctr: parseInt(p.clicks) / parseInt(p.impressions)
  })).sort((a, b) => b.ctr - a.ctr);
  placementAtribuido = formatarPlacement(comCTR[0].publisher_platform, comCTR[0].platform_position);
  confianca = 'media';
}

return [{
  json: {
    placement: placementAtribuido,
    confianca: confianca,
    breakdown_completo: insights.map(p => ({
      ...p,
      placement_formatado: formatarPlacement(p.publisher_platform, p.platform_position)
    })),
    total_cliques: insights.reduce((acc, p) => acc + parseInt(p.clicks), 0),
    total_impressoes: insights.reduce((acc, p) => acc + parseInt(p.impressions), 0)
  }
}];

const webhookData = $('Webhook Recebe Mensagem').first().json.body.data;

const mensagem =
  webhookData?.Message?.conversation ||
  webhookData?.Message?.extendedTextMessage?.text ||
  webhookData?.Message?.imageMessage?.caption ||
  webhookData?.Message?.videoMessage?.caption ||
  '';

if (!mensagem || typeof mensagem !== 'string') {
  throw new Error('Mensagem não encontrada no webhook. Estrutura recebida: ' + JSON.stringify(webhookData?.Message || {}));
}

const match = mensagem.match(/R\$\s*([\d.]+,?\d{0,2}|\d+)/i);

if (!match) {
  throw new Error('Valor não encontrado na mensagem: "' + mensagem + '"');
}

let valor = match[1]
  .replace(/\./g, '')
  .replace(',', '.');

return {
  json: {
    ...$json,
    mensagem_atendente: mensagem,
    valor_venda: parseFloat(valor),
    moeda: 'BRL'
  }
};

